"""Exact module generated by fixed saved corner classes under two twist increments."""
from pathlib import Path
from fractions import Fraction as F
from collections import deque
import json,hashlib
if not __debug__:raise RuntimeError('Do not run with -O')
B=Path(__file__).resolve().parent
PINNED_INPUTS = {'coupling.json': '9f81b7bf93b258958fa3d6347631e50f8165e57ad32166547431a3be9ed26bec', 'twist-action.json': 'b500e3b59ba262a81655d60441f31d6c7da74e022d308761f171cc7459f81e27', 'twist-pf.json': '0bbe693ff7e0e3e9a47541a253027cb433e6b301b52c152a469289356c71fd92', 'core-rigidity.json': 'e671bc7bfc6ba64f7143e9984ddec4a9cb337adaed4f96e4e4993a332e49abb2'}
for name,digest in PINNED_INPUTS.items():
    assert hashlib.sha256((B/name).read_bytes()).hexdigest()==digest, ('input changed',name)
D=json.loads((B/'coupling.json').read_text());A=json.loads((B/'twist-action.json').read_text())
P=json.loads((B/'twist-pf.json').read_text());C=json.loads((B/'core-rigidity.json').read_text())
room=next(r for r in P['rooms'] if r['tag']==D['tag']);E=room['intersection_matrix'];l=room['row_widths'];m=room['column_lengths']
H,V=len(l),len(m);dim=D['offset_dimension'];W=D['walls'];N=H+V
hforms=[[list(map(F,row)) for row in f] for f in A['core_period_derivatives']['horizontal']]
vforms=[[list(map(F,row)) for row in f] for f in A['core_period_derivatives']['vertical']]
assert len(hforms)==H and len(vforms)==V
assert all(not any(row[W:]) for f in hforms+vforms for row in f)

def insert(row,bs):
    row=list(map(F,row))
    for k,v in sorted(bs.items()):
        a=row[k]
        if a:row=[x-a*y for x,y in zip(row,v)]
    k=next((i for i,x in enumerate(row) if x),None)
    if k is None:return None
    a=row[k];row=[x/a for x in row];bs[k]=row;return row

def rank(rows):
    bs={}
    for r in rows:insert(r,bs)
    return len(bs)

def operators(x):
    # Normalize away positive a,b; scalar multiples generate the same module.
    # Both plus signs use the positive coordinate shears. Their algebraic
    # intersection orderings differ, as defined in the reviewed theorem.
    hh=[sum(F(E[i][j],l[i])*x[H+j] for j in range(V)) for i in range(H)]+[F(0)]*V
    vv=[F(0)]*H+[sum(F(E[i][j],m[j])*x[i] for i in range(H)) for j in range(V)]
    return hh,vv

def map_period(x):
    return [[sum(x[i]*hforms[i][k][j] for i in range(H))+sum(x[H+i]*vforms[i][k][j] for i in range(V)) for j in range(dim)] for k in (0,1)]

lengths=list(map(F,l+m))
def zero_hol(x):return sum(F(l[i])*x[i] for i in range(H))==0 and sum(F(m[j])*x[H+j] for j in range(V))==0

def seed_E(i):
    e=D['events'][i]
    return [[F(a)-2*F(b)+F(j==W+k) for j,(a,b) in enumerate(zip(e['target_image_forms'][k],e['corner_image_forms'][k]))] for k in (0,1)]

def module(indices):
    states=[];bs={};queue=deque()
    for i in indices:
        e=A['events'][i]
        for orientation in ('horizontal','vertical'):
            c=list(map(F,e[orientation]['twist_coefficients']))
            c=[x/F(A['summary'][orientation+'_shear']) for x in c]
            c=c+[F(0)]*V if orientation=='horizontal' else [F(0)]*H+c
            assert zero_hol(c)
            queue.append((c,0))
    maximum_depth=0
    while queue:
        c,depth=queue.popleft();assert zero_hol(c)
        reduced=insert(c,bs)
        if reduced is None:continue
        maximum_depth=max(maximum_depth,depth);states.append(reduced)
        for v in operators(reduced):queue.append((v,depth+1))
    # Independently check closure by re-reducing each operator image.
    for c in states:
        for v in operators(c):assert rank(states+[v])==len(states)
    periods=[row for c in states for row in map_period(c)]
    base=[row for i in indices for row in seed_E(i)]
    return {'indices':indices,'coefficient_module_dimension':len(states),'closure_depth_bound':maximum_depth,
        'core_period_relation_rank':rank(periods),'seed_vector_defect_rank':rank(base),'combined_orbit_vector_rank':rank(base+periods),
        'basis_states':[[str(x) for x in c] for c in states],'period_relation_rows':[[str(x) for x in r] for r in periods]}

one=module([0]);chosen=C['fixed_room_witness']['saved_blocks_selected']
assert chosen==list(range(9)), 'frozen rank selection differs from stated packet'
assert C['fixed_room_witness']['tag']==D['tag']
nine=module(chosen)
assert len(chosen)==9 and nine['combined_orbit_vector_rank']==W+1==26
assert one['combined_orbit_vector_rank']<26
# The axis length matrix has rank10; its zero-period ratio relations have at most9 independent room derivatives.
assert nine['core_period_relation_rank']==next(r for r in C['rooms'] if r['tag']==D['tag'])['axis_length_rank']-1==9
# A separately checked finite-field minor certifies full quotient rank.
allrows=[row for i in chosen for row in seed_E(i)]+[[F(x) for x in row] for row in nine['period_relation_rows']]
point=list(map(F,D['offset_base_point']));normals=list(map(tuple,D['offset_normals']))
tx=[F(x[0]) for x in normals]+[F(1),F(0),F(1),F(0)]
ty=[F(x[1]) for x in normals]+[F(0),F(1),F(0),F(1)]
assert rank([tx,ty,point])==3
assert all(sum(a*b for a,b in zip(row,v))==0 for row in allrows for v in (tx,ty,point))
prime=1000003
assert all(prime%d for d in range(2,1001))
free_columns=[j for j in range(dim) if j not in (0,W,W+1)]
assert len(free_columns)==26
modrows=[]
for row in allrows:
    assert all(x.denominator%prime for x in row)
    modrows.append([(row[j].numerator*pow(row[j].denominator,-1,prime))%prime for j in free_columns])
mb={};picked=[]
for index,row in enumerate(modrows):
    row=row[:]
    for j,basis in sorted(mb.items()):
        a=row[j]
        if a:row=[(x-a*y)%prime for x,y in zip(row,basis)]
    j=next((j for j,x in enumerate(row) if x),None)
    if j is not None:
        a=pow(row[j],-1,prime);mb[j]=[(x*a)%prime for x in row];picked.append(index)
assert len(picked)==26
minor=[modrows[i][:] for i in picked];det=1
for j in range(26):
    i=next(i for i in range(j,26) if minor[i][j])
    if i!=j:minor[j],minor[i]=minor[i],minor[j];det=-det
    pivot=minor[j][j];det=det*pivot%prime;inverse=pow(pivot,-1,prime)
    for i in range(j+1,26):
        a=minor[i][j]*inverse%prime
        minor[i]=[(x-a*y)%prime for x,y in zip(minor[i],minor[j])]
assert det%prime
minor_receipt={'prime':prime,'row_indices':picked,'columns':free_columns,'determinant_mod_prime':det%prime,
    'row_order':'two components per chosen seed, then chosen module period_relation_rows',
    'upper_rank_bound':'all rows annihilate three independent translation/scale vectors'}
summary={'single_seed_core_ratio_rank':one['core_period_relation_rank'],'single_seed_orbit_vector_rank':one['combined_orbit_vector_rank'],
    'chosen_seed_count':len(chosen),'chosen_indices':chosen,'chosen_core_ratio_rank':nine['core_period_relation_rank'],
    'chosen_orbit_vector_rank':nine['combined_orbit_vector_rank'],'full_quotient_rank':W+1,
    'seed_count_lower_bound_from_axis_isoperiodic_space':C['fixed_room_witness']['minimal_block_count_lower_bound']}
out={'status':'EXACT_FIXED_SEED_MODULE_RIGIDITY_PASS','summary':summary,'single_seed':one,'chosen_seed_packet':nine,'nonzero_quotient_minor':minor_receipt,
    'input_sha256':{name:hashlib.sha256((B/name).read_bytes()).hexdigest() for name in ('coupling.json','twist-action.json','twist-pf.json','core-rigidity.json')},
    'scope':'Fixed saved seed classes; algebraic twist-increment closure and actual period-derivative ranks. No new optical path/direction/word discovery. Universal seed realization and independence remain open.'}
(B/'seed-module.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(summary,indent=2))
